import type { Register, SessionContextUsage } from 'claude-code'

const BAR_WIDTH = 10

const compact = (n: number) => (n >= 1000 ? `${Math.round(n / 1000)}k` : `${n}`)

export const formatContext = ({ tokens, window, percent }: SessionContextUsage) => {
  if (tokens === undefined || percent === undefined) return `ctx —/${compact(window)}`
  const filled = Math.min(BAR_WIDTH, Math.round((percent / 100) * BAR_WIDTH))
  const bar = '█'.repeat(filled) + '░'.repeat(BAR_WIDTH - filled)
  return `ctx ${bar} ${percent}% · ${compact(tokens)}/${compact(window)}`
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const result = await next(e)
    $.ui.status(formatContext((await $.session.usage()).context))
    return result
  })

  on('session.measure', ($, e, next) => {
    $.ui.status(formatContext(e.context))
    return next(e)
  })
}

